function articleBySlug(string $slug): ?array
{
    $all = articleCatalog();
    if (!isset($all[$slug])) {
        return null;
    }
    $item = $all[$slug];
    $item['slug'] = $slug;
    $item['canonical'] = SITE_URL . $item['path'];
    $item['file_abs'] = dirname(__DIR__) . '/articole/' . $item['file'];
    return $item;
}

function articleSeoOverride(array $article): array
{
    return [
        'title' => $article['title'],
        'description' => $article['description'],
        'og_title' => $article['og_title'] ?? $article['title'],
        'og_type' => $article['og_type'] ?? 'article',
        'canonical' => $article['canonical'],
        'keywords' => $article['keywords'],
        'locale' => 'ro_RO',
        'alternates' => [
            'ro' => $article['canonical'],
            'x-default' => $article['canonical'],
        ],
    ];
}

